-- Stop all old Web/worker/CLI writers before migration; runtime roles must not be superusers/BYPASSRLS.
BEGIN;
CREATE TABLE "Organization" ("id" UUID NOT NULL, "name" TEXT NOT NULL, "slug" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "allowedIpCidrs" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Organization_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Organization_slug_key" ON "Organization"("slug");
INSERT INTO "Organization"("id","name","slug") VALUES ('00000000-0000-4000-8000-000000000001','Main','main');
ALTER TABLE "User" ADD COLUMN "platformOwner" BOOLEAN NOT NULL DEFAULT false;
CREATE TABLE "Membership" ("id" UUID NOT NULL, "userId" UUID NOT NULL, "organizationId" UUID NOT NULL, "role" "UserRole" NOT NULL DEFAULT 'OPERATOR', "active" BOOLEAN NOT NULL DEFAULT true, CONSTRAINT "Membership_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Membership_userId_organizationId_key" ON "Membership"("userId","organizationId");
CREATE INDEX "Membership_organizationId_idx" ON "Membership"("organizationId");
ALTER TABLE "Membership" ADD CONSTRAINT "Membership_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Membership" ADD CONSTRAINT "Membership_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
INSERT INTO "Membership"("id","userId","organizationId","role","active") SELECT gen_random_uuid(),"id",'00000000-0000-4000-8000-000000000001'::uuid,"role","active" FROM "User";
CREATE TABLE "PlatformSetting" ("key" TEXT NOT NULL,"value" JSONB NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PlatformSetting_pkey" PRIMARY KEY ("key"));
INSERT INTO "PlatformSetting" SELECT "key","value","updatedAt" FROM "AppSetting" WHERE "key" IN ('ingress.current');
DELETE FROM "AppSetting" WHERE "key" IN ('ingress.current');
