CREATE FUNCTION bitovp_keep_organization() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW."organizationId" IS DISTINCT FROM OLD."organizationId" THEN RAISE EXCEPTION 'Organization ownership is immutable' USING ERRCODE = '23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER "organization_immutable" BEFORE UPDATE ON "AppSetting" FOR EACH ROW EXECUTE FUNCTION bitovp_keep_organization();
ALTER TABLE "AppSetting" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "AppSetting" FORCE ROW LEVEL SECURITY;
CREATE POLICY "organization_scope" ON "AppSetting" USING ("organizationId" = (NULLIF(current_setting('bitovp.organization_id', true), '')::uuid)) WITH CHECK ("organizationId" = (NULLIF(current_setting('bitovp.organization_id', true), '')::uuid));
