-- These fixed-column SECURITY DEFINER functions are the only pre-scope tenant lookups.
-- Migration function ownership must have BYPASSRLS; the runtime application role must not.
ALTER TABLE "ApiToken" ADD COLUMN "userId" UUID;
ALTER TABLE "ApiToken" ADD CONSTRAINT "ApiToken_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE FUNCTION bitovp_auth_token(token_prefix TEXT) RETURNS TABLE ("id" UUID,"tokenHash" TEXT,"role" TEXT,"revokedAt" TIMESTAMP(3),"expiresAt" TIMESTAMP(3),"organizationId" UUID,"createdBy" TEXT,"userId" UUID) LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $$ SELECT "id","tokenHash","role","revokedAt","expiresAt","organizationId","createdBy","userId" FROM public."ApiToken" WHERE "prefix" = token_prefix $$;
CREATE FUNCTION bitovp_webhook_organization(token_hash TEXT) RETURNS TABLE ("organizationId" UUID) LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $$ SELECT DISTINCT "organizationId" FROM public."WebhookRegistration" WHERE "tokenHash" = token_hash $$;
COMMIT;
